def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    enemies = observation['opponent_position']
    obstacles = set(observation.get('obstacles', []))
    resources = observation.get('resources', [])
    def safe(nx, ny):
        return 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles
    directions = [(-1,0),(1,0),(0,-1),(0,1)]
    # Prioritize moving towards nearest resource
    target = None
    min_dist = float('inf')
    for rx, ry in resources:
        dist = abs(rx - x) + abs(ry - y)
        if dist < min_dist:
            min_dist = dist
            target = (rx, ry)
    # Move closer to target resource if found
    if target:
        dx = 0
        dy = 0
        if target[0] > x and safe(x+1, y):
            dx = 1
        elif target[0] < x and safe(x-1, y):
            dx = -1
        elif target[1] > y and safe(x, y+1):
            dy = 1
        elif target[1] < y and safe(x, y-1):
            dy = -1
        if dx != 0 or dy != 0:
            return [dx, dy]
    # Avoid enemies
    for ex, ey in [enemies]:
        if abs(ex - x) + abs(ey - y) == 1:
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if safe(nx, ny) and (nx != ex or ny != ey):
                    return [dx, dy]
    # Move towards opponent if safe
    ox, oy = enemies
    dx = 0
    dy = 0
    if ox > x and safe(x+1, y):
        dx = 1
    elif ox < x and safe(x-1, y):
        dx = -1
    elif oy > y and safe(x, y+1):
        dy = 1
    elif oy < y and safe(x, y-1):
        dy = -1
    if dx != 0 or dy != 0:
        return [dx, dy]
    # Stay in place if no better move
    return [0, 0]
